/**
 * Twisted vortex shader.
 *
 * ## The mathematical idea
 *
 * The same perspective as the tunnel — depth is the inverse of the radius —
 * but nothing else in common. The angle is twisted with depth: the further a
 * point is, the more it is turned, so that the ribs of the corridor wind into
 * a helix instead of running straight towards the centre. The whole thing
 * also pivots with time, and the vanishing point wanders along a slow
 * ellipse: the corridor is curved, not straight.
 *
 * The walls carry six ribs, read as a cosine of the twisted angle, and depth
 * bands that advance. The hue is not fixed: it turns around the wall with the
 * twisted angle and the depth, from one colour to the other. The glint
 * follows the ribs, where a band crosses them.
 *
 * The vanishing point is put out before it can beat against the pixel grid:
 * that is not decorative.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background.
 * - `uColorB` — the first hue of the walls.
 * - `uColorC` — the second hue, and the glint of the ribs.
 * - `uSpeed` — speed of travel.
 * - `uTwist` — twist of the ribs with depth.
 * - `uSpin` — rotation speed of the whole.
 * - `uRings` — density of the depth bands.
 */
export const WORMHOLE_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSpeed;
uniform float uTwist;
uniform float uSpin;
uniform float uRings;

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = (vUv - 0.5) * vec2(aspect, 1.0) * 2.0;

  // The vanishing point wanders: the corridor is curved, not straight.
  p -= 0.22 * vec2(sin(uTime * 0.6), cos(uTime * 0.45));

  float r = length(p);
  float angle = atan(p.y, p.x);
  float z = 1.0 / max(r, 0.01);
  float t = uTime * uSpeed;

  // The twist: the angle turns with depth; the whole thing pivots.
  float twisted = angle + z * uTwist * 0.25 + uTime * uSpin;

  // The depth advances; the bands are read from it as a sine.
  float depth = z * max(uRings, 1.0) * 0.25 - t * 3.0;

  // The walls: six twisted ribs, and bands that advance.
  float ribs = 0.5 + 0.5 * cos(twisted * 6.0);
  float band = smoothstep(0.25, 0.75, 0.5 + 0.5 * sin(depth));

  // The hue turns around the wall; the glint follows the ribs.
  float hue = 0.5 + 0.5 * sin(twisted * 3.0 + depth * 0.5);
  float glint = pow(ribs, 6.0) * band;

  // The vanishing point is put out before it can beat against the pixels.
  float far = smoothstep(0.03, 0.35, r);

  vec3 wall = mix(uColorB, uColorC, hue);
  vec3 colour = mix(uColorA, wall, (0.25 + 0.75 * band) * far * (0.5 + 0.5 * ribs));
  colour = mix(colour, uColorC, glint * far * 0.7);

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Twisted vortex: a corridor whose ribs wind into a helix, which pivots, and
 * whose hue turns around the wall.
 *
 * ## The principle
 *
 * Depth is the inverse of the radius, as in the tunnel; but the angle is
 * twisted with depth, the whole thing pivots with time and the vanishing
 * point wanders. The walls carry six helical ribs, bands that advance, and a
 * hue that slides from one colour to the other.
 *
 * What sets this entry apart from `tunnel`: the twist, the rotation, the
 * moving vanishing point, and two hues instead of one. The tunnel is a
 * straight, monochrome corridor; this is a vortex.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its
 * fallback. Reading the tokens, converting them to floats and re-reading them
 * when the theme changes all come from the engine — copying that here would
 * leave as many versions to maintain as there are backgrounds.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface — it grants only one
 * per backend — and under reduced motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { WORMHOLE_FRAGMENT } from './wormhole.shader.js'

/** What the escape hatch receives. */
export interface WormholeControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Props specific to this component. */
export interface WormholeOwnProps {
  /** Speed of travel. @defaultValue 0.5 */
  speed?: number
  /** Twist of the ribs with depth. @defaultValue 1 */
  twist?: number
  /** Rotation speed of the whole. @defaultValue 0.3 */
  spin?: number
  /** Density of the depth bands. @defaultValue 8 */
  rings?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<WormholeControls>
}

/** All props. */
export type WormholeProps = Customisable<WormholeOwnProps>

/** Tokens used by default: the background, the two hues of the walls. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-fuchsia-500',
  '--o-palette-cyan-400',
] as const

/** Default fallback: a frozen gradient, in the same tones. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-br o-from-zinc-50 dark:o-from-zinc-950 o-to-fuchsia-100 dark:o-to-fuchsia-950'

/**
 * Twisted vortex.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Wormhole className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Wormhole({
  speed = 0.5,
  twist = 1,
  spin = 0.3,
  rings = 8,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: WormholeProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: WORMHOLE_FRAGMENT,
    colors,
    uniforms: { uSpeed: speed, uTwist: twist, uSpin: spin, uRings: rings },
    name: 'wormhole',
    // Tight bands in the distance beat against the pixel grid at a reduced
    // density: at low quality, they spread apart.
    degrade: (quality) => ({
      uRings: quality === 'low' ? Math.min(rings, 5) : rings,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
